// Raw VM service verification only. This never invokes or skips Signal Java initialization.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class BoomSignalLookupProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context {public uint Kind,PC,Method,Depth;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [DllImport("kernel32.dll")] static extern bool VirtualProtect(IntPtr p,UIntPtr n,uint protection,out uint oldProtection);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint Release();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Get();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] args);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Lookup(ref Context c,[In] ulong[] args,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong FP(IntPtr fn,ref Context c,[In] ulong[] args,uint csr);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr PoolCreate(uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolRun(IntPtr p,IntPtr fn,IntPtr input,IntPtr output,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolDestroy(IntPtr p);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint ProbeBind(IntPtr p);
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static IntPtr Open(string path){IntPtr m=LoadLibraryExW(path,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"Signal module load failed: "+path);return m;}
    static T Fn<T>(IntPtr m,string name){IntPtr p=GetProcAddress(m,name);Check(p!=IntPtr.Zero,"Missing "+name);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static ulong Bits(IntPtr p){return unchecked((ulong)p.ToInt64());}
    static void Close(IntPtr m,IntPtr h){IntPtr p=GetProcAddress(m,"boom_release_trace_pool");if(p!=IntPtr.Zero)Check(Marshal.GetDelegateForFunctionPointer<Release>(p)()==0,"Signal producer Java frames active");if(h!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(h)!=0,"Signal heap cleanup failed");FreeLibrary(m);}
    static IntPtr Produce(Entry e,uint n){var c=new Context();ulong value=e(ref c,new ulong[]{n});Check(c.Kind==0&&c.Depth==0,"Signal String producer failed: "+c.Kind);return new IntPtr(unchecked((long)value));}
    static int Reachable(IntPtr roots,uint n){var seen=new HashSet<IntPtr>();var todo=new Stack<IntPtr>();for(int i=0;i<n;i++)todo.Push(Marshal.ReadIntPtr(roots,i*8));while(todo.Count!=0){IntPtr p=todo.Pop();if(p==IntPtr.Zero||!seen.Add(p))continue;uint flags=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((flags&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&seen.Count<1048576,"Malformed signal lookup root graph");for(int i=0;i<refs;i++)todo.Push(Marshal.ReadIntPtr(p,i*8));}return seen.Count;}
    static void GC(IntPtr m,IntPtr h){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n);int live=Reachable(roots,n);Check(Fn<Collect>(m,"boom_heap_collect")(h,roots,n)!=ulong.MaxValue&&Marshal.ReadInt64(h,56)==live,"Signal String producer root graph mismatch");}
    public static void Raw(string dll,string runtime,byte[] expected){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(8*1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1&&expected.Length==8*65536,"Raw signal setup failed");var e=Fn<Entry>(m,"boom_entry");var lookup=Fn<Lookup>(r,"boom_signal_find");IntPtr pool=Fn<Get>(m,"boom_get_prefix_string_pool")();for(int i=0;i<expected.Length;i++){IntPtr s=Produce(e,(uint)i);long before=Marshal.ReadInt64(h,56);var c=new Context();ulong value=lookup(ref c,new ulong[]{Bits(s)},pool);ulong want=expected[i]==255?uint.MaxValue:expected[i];Check(value==want&&c.Kind==0&&c.Depth==0&&Marshal.ReadInt64(h,56)==before,"Signal lookup differs from JVM at raw UTF16 case "+i);if((i&255)==255)GC(m,h);}GC(m,h);}finally{Close(m,h);FreeLibrary(r);}}
    public static void Literals(string dll,string runtime,string adapter,string fp,int[] expected,uint[] kinds){IntPtr m=Open(dll),r=Open(runtime),a=Open(adapter),f=Open(fp),h=IntPtr.Zero,pool=IntPtr.Zero,input=IntPtr.Zero,output=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1&&expected.Length==32&&kinds.Length==32,"Signal literal setup failed");var e=Fn<Entry>(m,"boom_entry");var lookup=Fn<Lookup>(r,"boom_signal_find");IntPtr stringPool=Fn<Get>(m,"boom_get_prefix_string_pool")();var values=new IntPtr[32];for(uint i=0;i<32;i++)values[i]=Produce(e,i);GC(m,h);long baseline=Marshal.ReadInt64(h,56);Check(Fn<ProbeBind>(a,"boom_signal_probe_bind")(stringPool)==0,"Signal test adapter bind failed");var invoke=Fn<FP>(f,"boom_probe_numeric");foreach(uint csr in new uint[]{0x1f80,0xffc0})for(int i=0;i<32;i++){var c=new Context{PC=17,Method=23};ulong value=invoke(GetProcAddress(a,"boom_signal_probe_job"),ref c,new ulong[]{Bits(values[i])},csr);Check(value==unchecked((uint)expected[i])&&c.Kind==kinds[i]&&c.PC==17&&c.Method==23&&c.Depth==csr&&Marshal.ReadInt64(h,56)==baseline,"Signal literal/FP context differs from JVM: "+i);}
        var pending=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(lookup(ref pending,new ulong[]{0},IntPtr.Zero)==0&&pending.Kind==9&&pending.PC==17&&pending.Method==23&&pending.Depth==3,"Signal lookup changed pending exception");
        IntPtr copy=Marshal.AllocHGlobal(80);try{byte[] data=new byte[80];Marshal.Copy(stringPool,data,0,80);foreach(int off in new[]{0,4,16,40,48,64}){Marshal.Copy(data,0,copy,80);if(off<24)Marshal.WriteInt32(copy,off,off==16?65537:7);else Marshal.WriteIntPtr(copy,off,IntPtr.Zero);var c=new Context();Check(lookup(ref c,new ulong[]{Bits(values[3])},copy)==0&&c.Kind==7,"Malformed signal string pool accepted: "+off);}IntPtr foreign=Fn<Create>(m,"boom_heap_create")(65536);try{Check(foreign!=IntPtr.Zero,"Foreign signal heap failed");Marshal.Copy(data,0,copy,80);Marshal.WriteIntPtr(copy,48,foreign);var c=new Context();Check(lookup(ref c,new ulong[]{Bits(values[3])},copy)==0&&c.Kind==7,"Signal lookup accepted foreign heap");}finally{Check(Fn<Destroy>(m,"boom_heap_destroy")(foreign)!=0,"Foreign signal cleanup failed");}}finally{Marshal.FreeHGlobal(copy);}
        IntPtr chars=Marshal.ReadIntPtr(values[3]);foreach(int off in new[]{-32,-24,-20,-16,-8}){long old=Marshal.ReadInt64(chars,off);try{Marshal.WriteInt64(chars,off,7);var c=new Context();Check(lookup(ref c,new ulong[]{Bits(values[3])},stringPool)==0&&c.Kind==7,"Malformed signal backing accepted");}finally{Marshal.WriteInt64(chars,off,old);}}
        const uint n=2049;pool=Fn<PoolCreate>(r,"boom_pool_create")(8);Check(pool!=IntPtr.Zero,"Signal worker pool failed");input=Marshal.AllocHGlobal((int)n*128);output=Marshal.AllocHGlobal((int)n*32);for(int i=0;i<n;i++)Marshal.WriteIntPtr(input,i*128,values[i%31]);
        for(int batch=0;batch<3;batch++){Check(Fn<PoolRun>(r,"boom_pool_run")(pool,GetProcAddress(a,"boom_signal_probe_job"),input,output,n)==0,"Signal worker batch failed");for(int i=0;i<n;i++)Check(unchecked((ulong)Marshal.ReadInt64(output,i*32))==unchecked((uint)expected[i%31])&&Marshal.ReadInt64(output,i*32+8)==0&&Marshal.ReadInt64(output,i*32+16)==0&&Marshal.ReadInt64(output,i*32+24)==0,"Signal worker result/context mismatch");Check(Marshal.ReadInt64(h,56)==baseline,"Signal workers allocated guest objects");GC(m,h);}
        Check(Fn<PoolDestroy>(r,"boom_pool_destroy")(pool)==0,"Signal workers still active");pool=IntPtr.Zero;var alloc=Fn<Alloc>(r,"boom_heap_alloc");while(alloc(h,4096,0,267)!=IntPtr.Zero){}while(alloc(h,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(h,56);for(int i=0;i<8193;i++){var c=new Context();uint index=(uint)(i%32);Check(lookup(ref c,new ulong[]{Bits(values[index])},stringPool)==unchecked((uint)expected[index])&&c.Kind==kinds[index]&&c.Depth==0&&Marshal.ReadInt64(h,56)==full,"Full heap signal lookup mismatch/allocation");}GC(m,h);
    }finally{if(pool!=IntPtr.Zero)Check(Fn<PoolDestroy>(r,"boom_pool_destroy")(pool)==0,"Signal workers active at cleanup");if(input!=IntPtr.Zero)Marshal.FreeHGlobal(input);if(output!=IntPtr.Zero)Marshal.FreeHGlobal(output);Close(m,h);FreeLibrary(a);FreeLibrary(f);FreeLibrary(r);}}
    public static void EmptyBoundary(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(20*4096);Check(h!=IntPtr.Zero,"Signal boundary heap failed");IntPtr end=Marshal.ReadIntPtr(h,24);Check((end.ToInt64()&4095)==16,"Review signal test heap split");end=new IntPtr(end.ToInt64()-16);Marshal.WriteInt64(h,16,Marshal.ReadInt64(h,16)-16);Marshal.WriteIntPtr(h,24,end);Marshal.WriteIntPtr(h,32,end);Marshal.WriteInt64(h,40,Marshal.ReadInt64(h,40)+2);Marshal.WriteInt64(h,128,Marshal.ReadInt64(h,128)-16);Check(Fn<Bind>(m,"boom_bind_heap")(h)==1,"Signal boundary heap bind failed");IntPtr empty=Produce(Fn<Entry>(m,"boom_entry"),7),stringPool=Fn<Get>(m,"boom_get_prefix_string_pool")();GC(m,h);var alloc=Fn<Alloc>(r,"boom_heap_alloc");long left=Marshal.ReadInt64(h,16)-Marshal.ReadInt64(h,48);Check(alloc(h,checked((ulong)(left-64)),0,267)!=IntPtr.Zero,"Signal boundary padding failed");IntPtr last=alloc(h,0,0,261);Check(last==end,"Signal empty backing not at heap end");Marshal.WriteIntPtr(empty,last);Check(VirtualProtect(end,new UIntPtr(4096),1,out uint protection),"Signal guard page failed");try{var c=new Context();Check(Fn<Lookup>(r,"boom_signal_find")(ref c,new ulong[]{Bits(empty)},stringPool)==uint.MaxValue&&c.Kind==0,"Empty signal lookup touched guard page or returned wrong result");}finally{Check(VirtualProtect(end,new UIntPtr(4096),protection,out uint discarded),"Signal guard page restoration failed");}GC(m,h);}finally{Close(m,h);FreeLibrary(r);}}
}
